import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Limitation de débit","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/ratelimit.md","filePath":"fr/advanced/ratelimit.md","lastUpdated":1784903584000}'),n={name:"fr/advanced/ratelimit.md"};function r(l,e,o,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="limitation-de-debit" tabindex="-1">Limitation de débit <a class="header-anchor" href="#limitation-de-debit" aria-label="Permalink to &quot;Limitation de débit&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp dispose d&#39;un limiteur de débit intégré qui empêche le LLM d&#39;appeler le même point d&#39;accès API trop fréquemment. Cela protège contre les appels en double accidentels et respecte les limites de débit des API.</p><h2 id="comment-cela-fonctionne" tabindex="-1">Comment cela fonctionne <a class="header-anchor" href="#comment-cela-fonctionne" aria-label="Permalink to &quot;Comment cela fonctionne&quot;">​</a></h2><p>Chaque point d&#39;accès a une période de refroidissement. Si le LLM tente d&#39;appeler le même point d&#39;accès pendant le refroidissement, l&#39;appel est rejeté avec une erreur structurée.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(point d&#39;accès) → exécute</span></span>
<span class="line"><span>t=2s  → invoke(point d&#39;accès) → rejeté avec erreur rate_limit</span></span>
<span class="line"><span>t=12s → invoke(point d&#39;accès) → exécute (le refroidissement est passé)</span></span></code></pre></div><h3 id="comportement-par-defaut" tabindex="-1">Comportement par défaut <a class="header-anchor" href="#comportement-par-defaut" aria-label="Permalink to &quot;Comportement par défaut&quot;">​</a></h3><ul><li><strong>Refroidissement :</strong> 10 secondes par point d&#39;accès</li><li><strong>Portée :</strong> Par point d&#39;accès — appeler le point d&#39;accès A n&#39;affecte pas le point d&#39;accès B</li><li><strong>Réponse d&#39;erreur :</strong> Le LLM reçoit une <code>LLMError</code> avec le code <code>rate_limit</code> et un message indiquant combien de temps attendre</li><li><strong>Réinitialisation :</strong> Après 10 secondes d&#39;inactivité sur ce point d&#39;accès</li></ul><h3 id="format-d-erreur" tabindex="-1">Format d&#39;erreur <a class="header-anchor" href="#format-d-erreur" aria-label="Permalink to &quot;Format d&#39;erreur&quot;">​</a></h3><p>Lorsque la limite de débit est atteinte, le LLM reçoit :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;limite de débit dépassée pour le point d&#39;accès </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> : réessayez dans 8 secondes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Attendez la fin de la période de refroidissement, puis essayez à nouveau d&#39;invoquer le point d&#39;accès. Utilisez l&#39;outil de recherche pour trouver d&#39;autres points d&#39;accès que vous pouvez appeler entre-temps.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Le LLM peut utiliser ces informations pour attendre et réessayer, ou passer à un point d&#39;accès différent.</p><h3 id="pourquoi-cela-existe" tabindex="-1">Pourquoi cela existe <a class="header-anchor" href="#pourquoi-cela-existe" aria-label="Permalink to &quot;Pourquoi cela existe&quot;">​</a></h3><ul><li><strong>Empêche les appels en double accidentels</strong> — le LLM pourrait appeler le même point d&#39;accès plusieurs fois en succession rapide</li><li><strong>Protège contre les limites de débit des API</strong> — de nombreuses API ont leurs propres limites de débit, et les atteindre provoquerait des erreurs</li><li><strong>Économise les ressources</strong> — réduit le trafic réseau inutile</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Vous pouvez désactiver le limiteur de débit ou modifier l&#39;intervalle de refroidissement :</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Désactiver complètement le limiteur de débit</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Intervalle de refroidissement personnalisé</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>Type :</strong> <code>bool</code></li><li><strong>Défaut :</strong> <code>false</code></li><li><strong>Effet :</strong> Lorsque <code>true</code>, le limiteur de débit par point d&#39;accès est désactivé. Le LLM peut appeler le même point d&#39;accès de manière répétée sans attendre.</li><li><strong>Quand l&#39;activer :</strong> Tests, débogage, ou lorsque vous devez appeler le même point d&#39;accès plusieurs fois en succession rapide.</li><li><strong>Quand le laisser désactivé (recommandé) :</strong> Production. Le limiteur de débit empêche les abus accidentels.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>Type :</strong> durée (format Go : <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>Défaut :</strong> <code>10s</code></li><li><strong>Effet :</strong> Définit la période de refroidissement entre les appels au même point d&#39;accès.</li><li><strong>Quand augmenter :</strong> API avec des limites de débit strictes (par exemple, 10 requêtes par minute).</li><li><strong>Quand diminuer :</strong> API internes où vous contrôlez la charge.</li><li><strong>Exemples :</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="notes-importantes" tabindex="-1">Notes importantes <a class="header-anchor" href="#notes-importantes" aria-label="Permalink to &quot;Notes importantes&quot;">​</a></h2><ul><li><strong>Suivi par point d&#39;accès</strong> — chaque point d&#39;accès est suivi indépendamment. Appeler un point d&#39;accès n&#39;affecte pas les autres.</li><li><strong>Erreur retournée au LLM</strong> — le second appel pendant le refroidissement est rejeté avec une erreur <code>rate_limit</code>. Le LLM reçoit la durée du refroidissement et peut réessayer après avoir attendu.</li><li><strong>Aucun nettoyage nécessaire</strong> — le limiteur de débit suit les points d&#39;accès automatiquement et ne nécessite pas de maintenance.</li></ul>`,23)])])}const m=i(n,[["render",r]]);export{h as __pageData,m as default};
